parameters.jsCode:
const allCandidates = [];

// 1. Extract all candidates from the incoming agent outputs
for (const item of $input.all()) {
  let candidates = [];

  // Look for the array inside the 'output' key (Standard AI Agent behavior)
  if (item.json.output && item.json.output.outreach_candidates) {
    candidates = item.json.output.outreach_candidates;
  } 
  // Look for it with a hyphen just in case it parsed that way
  else if (item.json.output && item.json.output['outreach-candidates']) {
    candidates = item.json.output['outreach-candidates'];
  }
  // Fallback: Look at the root just in case
  else if (item.json.outreach_candidates) {
    candidates = item.json.outreach_candidates;
  }

  // If we successfully found the array, push it into our main list
  if (Array.isArray(candidates)) {
    allCandidates.push(...candidates);
  }
}

// 2. Deduplicate based on the 'link' (URL)
const uniqueCandidatesMap = new Map();

for (const candidate of allCandidates) {
  // Safety check: Skip if the agent hallucinated and didn't provide a link
  if (!candidate.link) continue; 

  // Normalize the URL (lowercase and remove trailing slashes) to catch matching duplicates
  const url = candidate.link.toLowerCase().trim().replace(/\/$/, ""); 

  if (uniqueCandidatesMap.has(url)) {
    // If the URL already exists in our map, merge the tags
    const existingCandidate = uniqueCandidatesMap.get(url);

    // Check if the tag isn't already included before adding it
    if (!existingCandidate.tags.includes(candidate.tags)) {
       existingCandidate.tags = existingCandidate.tags + ", " + candidate.tags;
    }
  } else {
    // If it's a new URL, add it to our map
    uniqueCandidatesMap.set(url, candidate);
  }
}

// 3. Output the cleaned data as individual n8n items
const finalItems = Array.from(uniqueCandidatesMap.values()).map(candidate => ({
  json: candidate
}));

return finalItems;

