const out = [];
for (const item of $input.all()) {
  let url = String(item.json.url || '').trim();
  if (url && !/^https?:\/\//i.test(url)) url = 'https://' + url.replace(/^\/+/, '');
  const crawl = item.json.crawl_subpages === true || String(item.json.crawl_subpages).toLowerCase() === 'true';
  out.push({ json: { url, crawl_subpages: crawl } });
}
return out;

function analyzePage(html, pageUrl, maxText) {
  html = String(html || '');
  const decode = (s) => String(s || '')
    .replace(/&#64;|&#x40;/gi, '@').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');
  const hostOf = (u) => { const hm = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return hm ? hm[1].toLowerCase().replace(/^www\./, '') : ''; };
  const abs = (href) => {
    href = String(href || '').trim();
    if (!href || /^(mailto|tel|javascript|data):/i.test(href)) return null;
    if (/^https?:\/\//i.test(href)) return href;
    const bm = String(pageUrl).match(/^(https?:)\/\/([^\/?#]+)(\/[^?#]*)?/i);
    if (!bm) return null;
    if (href.startsWith('//')) return bm[1] + href;
    if (href.startsWith('/')) return bm[1] + '//' + bm[2] + href;
    if (href.startsWith('?')) return bm[1] + '//' + bm[2] + (bm[3] || '/') + href;
    return bm[1] + '//' + bm[2] + (bm[3] || '/').replace(/[^\/]*$/, '') + href;
  };
  const host = hostOf(pageUrl);

  const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  const metaMatch = html.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)["']/i);

  const cleaned = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ');
  const text = decode(cleaned.replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|h[1-6]|tr|section)>/gi, '\n').replace(/<[^>]+>/g, ' '))
    .replace(/[ \t]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();

  const emailSource = decode(html).replace(/\s?\[\s?(at|ät)\s?\]\s?|\s?\(\s?(at|ät)\s?\)\s?/gi, '@').replace(/\s?\[\s?(dot|punkt)\s?\]\s?|\s?\(\s?(dot|punkt)\s?\)\s?/gi, '.');
  const emails = [...new Set((emailSource.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])
    .map(e => e.toLowerCase())
    .filter(e => !/\.(png|jpe?g|gif|svg|webp|css|js)$/i.test(e))
    .filter(e => !/(sentry|wixpress|example\.(com|org)|domain\.(com|de)|email\.com|yourname|@2x)/i.test(e)))].slice(0, 15);

  const phones = [...new Set((html.match(/href=["']tel:([^"']+)["']/gi) || []).map(t => decode(t.replace(/^href=["']tel:/i, '').replace(/["']$/, ''))))].slice(0, 5);

  const links = [];
  const linkRe = /<a\b[^>]*href=["']([^"'#][^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = linkRe.exec(html)) && links.length < 600) {
    const url = abs(decode(m[1]));
    if (!url || !/^https?:/i.test(url)) continue;
    links.push({ url, text: decode(m[2].replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim().slice(0, 80) });
  }

  const contactRe = /(impressum|imprint|kontakt|contact|legal|rechtliches|about|ueber-uns|uber-uns|über uns|team|redaktion|editorial|presse|press|submit|einreichen|eintragen|add-?event|veranstaltung|termine?-melden|event-melden|advertis|mediadaten|werben|mitmachen|guidelines|regeln|rules)/i;
  const sameHost = (u) => hostOf(u) === host;
  const seen = new Set();
  const contactPages = [];
  for (const l of links) {
    const key = l.url.replace(/[?#].*$/, '').replace(/\/$/, '');
    if (seen.has(key) || !sameHost(l.url)) continue;
    if (contactRe.test(l.url) || contactRe.test(l.text)) {
      seen.add(key);
      contactPages.push({ url: l.url, text: l.text });
    }
    if (contactPages.length >= 10) break;
  }

  const socialRe = /(facebook\.com|instagram\.com|linkedin\.com|twitter\.com|x\.com|reddit\.com|t\.me|telegram\.me|xing\.com|meetup\.com|tiktok\.com|youtube\.com|whatsapp\.com|discord\.(gg|com)|mastodon)/i;
  const socialLinks = [...new Set(links.filter(l => socialRe.test(l.url) && !/sharer|share\?|intent\/tweet/i.test(l.url)).map(l => l.url))].slice(0, 10);

  const forms = [];
  const formRe = /<form\b([^>]*)>([\s\S]*?)<\/form>/gi;
  while ((m = formRe.exec(html)) && forms.length < 5) {
    const attrs = m[1];
    const body = m[2];
    const action = (attrs.match(/action=["']([^"']*)["']/i) || [])[1] || '';
    const method = ((attrs.match(/method=["']([^"']*)["']/i) || [])[1] || 'get').toUpperCase();
    const fields = [];
    const fieldRe = /<(input|textarea|select)\b([^>]*)>/gi;
    let f;
    while ((f = fieldRe.exec(body)) && fields.length < 30) {
      const a = f[2];
      const type = ((a.match(/type=["']?([^"'\s>]+)/i) || [])[1] || f[1]).toLowerCase();
      if (['hidden', 'submit', 'button'].includes(type)) continue;
      const name = (a.match(/name=["']?([^"'\s>]+)/i) || [])[1] || '';
      const ph = (a.match(/placeholder=["']([^"']*)["']/i) || [])[1] || '';
      const req = /\brequired\b/i.test(a);
      fields.push([type, name, ph].filter(Boolean).join(':') + (req ? '*' : ''));
    }
    const labels = [...body.matchAll(/<label[^>]*>([\s\S]*?)<\/label>/gi)].map(x => decode(x[1].replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim()).filter(Boolean).slice(0, 20);
    const submit = decode(((body.match(/<button[^>]*>([\s\S]*?)<\/button>/i) || [])[1] || (body.match(/type=["']submit["'][^>]*value=["']([^"']*)["']/i) || [])[1] || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
    const isSearch = /search|suche|newsletter/i.test(attrs + submit) && fields.length <= 2;
    forms.push({
      action: action ? abs(decode(action)) : pageUrl,
      method,
      purpose_hint: isSearch ? 'search/newsletter (probably not a submission form)' : (fields.some(x => x.startsWith('password')) ? 'login/registration' : 'content/contact form'),
      fields,
      labels,
      submit_text: submit.slice(0, 60),
      has_password_field: fields.some(x => x.startsWith('password')),
      has_file_upload: fields.some(x => x.startsWith('file')),
    });
  }

  const lower = text.toLowerCase();
  const signalWords = ['login', 'log in', 'anmelden', 'einloggen', 'registrieren', 'registrierung', 'register', 'sign up', 'sign in', 'create account', 'konto erstellen', 'benutzerkonto', 'mitglied werden', 'membership', 'members only', 'nur für mitglieder', 'join group', 'gruppe beitreten', 'beitreten', 'moderator', 'admin', 'freischaltung', 'approval', 'geprüft', 'kostenpflichtig', 'gebühr', 'fee', 'premium', 'sponsored', 'captcha'];
  const registrationSignals = signalWords.filter(w => lower.includes(w));
  const hasCaptcha = /recaptcha|hcaptcha|turnstile|friendlycaptcha/i.test(html);

  const socialPage = socialRe.test(host);
  const loginWallLikely = socialPage && (text.length < 1500 || /log in|anmelden|sign up|registrieren/i.test(text.slice(0, 1500)));

  return {
    url: pageUrl,
    title: decode(titleMatch ? titleMatch[1] : '').replace(/\s+/g, ' ').trim(),
    meta_description: decode(metaMatch ? metaMatch[1] : ''),
    is_social_media_url: socialPage,
    login_wall_likely: loginWallLikely,
    emails,
    phones,
    forms,
    has_captcha: hasCaptcha,
    registration_signals: registrationSignals,
    contact_page_candidates: contactPages,
    social_links: socialLinks,
    text_excerpt: text.slice(0, maxText),
    text_truncated: text.length > maxText,
  };
}

const req = $('Normalize URL').first().json;
const res = $input.first().json;
const html = typeof res.data === 'string' ? res.data : '';
const result = analyzePage(html, req.url, 6000);
result.fetch_ok = html.length > 0 && !res.error;
if (res.error) result.fetch_error = typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error)).slice(0, 300);
if (!html) result.note = 'Page could not be fetched (blocked, login wall, JS-only site or timeout). Use web search to find contact details instead.';
result.crawl_subpages = req.crawl_subpages;
return [{ json: result }];

const decode = (s) => String(s || '').replace(/&#64;|&#x40;/gi, '@').replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;/g, "'");
const toText = (h) => decode(h.replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, ' ').replace(/<br\s*\/?>|<\/(p|div|li|h[1-6]|tr)>/gi, '\n').replace(/<[^>]+>/g, ' ')).replace(/[ \t]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();
const findEmails = (h) => [...new Set((decode(h).replace(/\s?[\[\(]\s?(at|ät)\s?[\]\)]\s?/gi, '@').replace(/\s?[\[\(]\s?(dot|punkt)\s?[\]\)]\s?/gi, '.').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).map(e => e.toLowerCase()).filter(e => !/\.(png|jpe?g|gif|svg|webp|css|js)$/i.test(e) && !/(sentry|wixpress|example\.(com|org)|@2x)/i.test(e)))].slice(0, 15);
const signalWords = ['login', 'anmelden', 'einloggen', 'registrieren', 'registrierung', 'register', 'sign up', 'create account', 'konto erstellen', 'mitglied werden', 'membership', 'members only', 'beitreten', 'freischaltung', 'approval', 'geprüft', 'kostenpflichtig', 'gebühr', 'fee', 'premium'];

const main = $('Parse Page').first().json;
const requested = $('Pick Contact Subpages').all();
const subpages = $input.all().map((item, i) => {
  const url = requested[i] ? requested[i].json.url : '';
  const html = typeof item.json.data === 'string' ? item.json.data : '';
  if (!html) return { url, fetch_ok: false };
  const text = toText(html);
  const lower = text.toLowerCase();
  const formCount = (html.match(/<form\b/gi) || []).length;
  return {
    url,
    fetch_ok: true,
    title: decode((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '').trim(),
    emails: findEmails(html),
    phones: [...new Set((html.match(/href=["']tel:([^"']+)["']/gi) || []).map(t => t.replace(/^href=["']tel:/i, '').replace(/["']$/, '')))].slice(0, 5),
    form_count: formCount,
    form_has_password_field: /<input[^>]+type=["']?password/i.test(html),
    has_captcha: /recaptcha|hcaptcha|turnstile|friendlycaptcha/i.test(html),
    registration_signals: signalWords.filter(w => lower.includes(w)),
    text_excerpt: text.slice(0, 2500),
  };
});
const allEmails = [...new Set([...(main.emails || []), ...subpages.flatMap(s => s.emails || [])])];
const allPhones = [...new Set([...(main.phones || []), ...subpages.flatMap(s => s.phones || [])])];
const mainOut = Object.assign({}, main, { text_excerpt: String(main.text_excerpt || '').slice(0, 3000) });
return [{ json: Object.assign(mainOut, { all_emails: allEmails, all_phones: allPhones, crawled_subpages: subpages }) }];
